public StringFullResponseHolder go(Request request) throws IOException, InterruptedException
{
  return go(request, new StringFullResponseHandler(StandardCharsets.UTF_8));
}

/**
 * Executes a Request object aimed at the leader. Throws IOException if the leader cannot be located.
 */
public <T, H extends FullResponseHolder<T>> H go(Request request, HttpResponseHandler<H, H> responseHandler)
    throws IOException, InterruptedException
{
  Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
  for (int counter = 0; counter < MAX_RETRIES; counter++) {
    final H fullResponseHolder;
    try {
      try {
        fullResponseHolder = httpClient.go(request, responseHandler).get();
      }
      catch (ExecutionException e) {
        // Unwrap IOExceptions and ChannelExceptions, re-throw others
        Throwables.propagateIfInstanceOf(e.getCause(), IOException.class);
        Throwables.propagateIfInstanceOf(e.getCause(), ChannelException.class);
        throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
      }
    }
    catch (IOException | ChannelException ex) {
      // can happen if the node is stopped.
      log.warn(ex, "Request[%s] failed.", request.getUrl());
      Iterator<DiscoveryDruidNode> nodeIterator = druidNodeDiscovery.getAllNodes().iterator();
      String leader = null;
      if (nodeIterator.hasNext()) {
        DiscoveryDruidNode discoveryNode = nodeIterator.next();
        DruidNode druidNode = discoveryNode.getDruidNode();
        String nodeHost = druidNode.getHost();
        int tlsPort = druidNode.getTlsPort();
        int plaintextPort = druidNode.getPlaintextPort();
        boolean tlsEnabled = druidNode.isEnableTlsPort();
        boolean plaintextEnabled = druidNode.isEnablePlaintextPort();
        String serviceScheme = tlsPort >= 0 ? "https" : "http";
        String hostAndPortToUse = null;
        if (tlsEnabled) {
          hostAndPortToUse = HostAndPort.fromParts(nodeHost, tlsPort).toString();
        } else if (plaintextEnabled && plaintextPort < 0) {
          hostAndPortToUse = HostAndPort.fromString(nodeHost).toString();
        } else if (plaintextEnabled) {
          hostAndPortToUse = HostAndPort.fromParts(nodeHost, plaintextPort).toString();
        }
        leader = StringUtils.format("%s://%s", serviceScheme, hostAndPortToUse);
      }
      currentKnownLeader.set(leader);
      if (leader == null) {
        throw new IOE("No known server");
      }
      try {
        URL failedUrl = request.getUrl();
        String query = failedUrl.getQuery();
        String path = failedUrl.getPath();
        URL retryUrl;
        if (query == null) {
          retryUrl = new URL(StringUtils.format("%s%s", leader, path));
        } else {
          retryUrl = new URL(StringUtils.format("%s%s?%s", leader, path, query));
        }
        Request retryRequest = new Request(request.getMethod(), retryUrl);
