 *
 * The caller can pass in the set of non-2xx response codes that should be handled (returned) by it. Any other
 * non-2xx response causes the leader cache to be refreshed and the request to be retried, in the same way as an
 * IOException.
 */
public <T, H extends FullResponseHolder<T>> H go(
    Request request,
    HttpResponseHandler<H, H> responseHandler,
    Set<Integer> responseCodesToHandle
) throws IOException, InterruptedException
{
  Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
