      ));

      request = withUrl(request, redirectUrl);
    } else if (shouldReturnResponse(responseStatus, responseCodesToHandle)) {
      return fullResponseHolder;
    } else {
      log.warn(
          "Request[%s] failed with status[%s]. Refreshing leader cache and retrying.",
          request.getUrl(),
          responseStatus
      );

      // If this was the last attempt, return the response to the caller as before rather than throwing.
      if (counter == MAX_RETRIES - 1) {
        return fullResponseHolder;
      }

      final String leader = refreshLeader();
      if (leader == null) {
        return fullResponseHolder;
      }
      request = makeRetryRequest(request, leader);
    }
  }

  throw new IOE("Retries exhausted, couldn't fulfill request to [%s].", request.getUrl());
}

public String findCurrentLeader()
{
  Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
  final StringFullResponseHolder responseHolder;
  try {
    responseHolder = go(makeRequest(HttpMethod.GET, leaderRequestPath));
  }
  catch (Exception ex) {
    throw new ISE(ex, "Couldn't find leader.");
  }

  if (responseHolder.getStatus().getCode() == 200) {
    String leaderUrl = responseHolder.getContent();

    //verify this is valid url
    try {
      URL validatedUrl = new URL(leaderUrl);
      currentKnownLeader.set(leaderUrl);

      // validatedUrl.toString() is returned instead of leaderUrl or else teamcity build fails because of breaking
      // the rule of ignoring new URL(leaderUrl) object.
      return validatedUrl.toString();
    }
    catch (MalformedURLException ex) {
      log.error(ex, "Received malformed leader url[%s].", leaderUrl);
    }
  }

  throw new ISE(
      "Couldn't find leader, failed response status is [%s] and content [%s].",
      responseHolder.getStatus().getCode(),
      responseHolder.getContent()
  );
}

private boolean shouldReturnResponse(
    HttpResponseStatus responseStatus,
    @Nullable Set<Integer> responseCodesToHandle
)
{
  // 503 and 504 are returned by proxies/sidecars when the requested endpoint is unavailable. Always retry these
  // after refreshing the leader cache.
  if (HttpResponseStatus.SERVICE_UNAVAILABLE.equals(responseStatus)
      || HttpResponseStatus.GATEWAY_TIMEOUT.equals(responseStatus)) {
    return false;
  }

  final int responseCode = responseStatus.getCode();
  if (responseCode >= 200 && responseCode < 300) {
    return true;
  }

  // Preserve the old behavior of returning other non-2xx responses unless the caller has explicitly asked for
  // them to be handled (returned) by passing a set of response codes.
  return responseCodesToHandle == null || responseCodesToHandle.contains(responseCode);
}

@Nullable
private String refreshLeader()
{
  Iterator<DiscoveryDruidNode> nodeIterator = druidNodeDiscovery.getAllNodes().iterator();
  String leader = null;
  if (nodeIterator.hasNext()) {
    DiscoveryDruidNode discoveryNode = nodeIterator.next();
    DruidNode druidNode = discoveryNode.getDruidNode();
    String nodeHost = druidNode.getHost();
    int tlsPort = druidNode.getTlsPort();
    int plaintextPort = druidNode.getPlaintextPort();
    boolean tlsEnabled = druidNode.isEnableTlsPort();
    boolean plaintextEnabled = druidNode.isEnablePlaintextPort();
